import math

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def check_solution(P):
    # P must be prime, P > 13
    D = 4 * P**3 - 3

    # Check if D is a perfect square
    k_float = math.isqrt(D)
    if k_float * k_float != D:
        return None # D is not a perfect square

    k = k_float

    # Calculate q. Since D = 4P^3 - 3, D is odd (4P^3 is even, -3 is odd). 
    # Thus k is odd, and k+1 is even. q will be an integer.
    q = (k + 1) // 2

    # Verify constraints
    if q <= 0:
        return None

    if q == P:
        return None # q must be different from P

    if not is_prime(q):
        return None # q must be prime

    return (P, q)

# Primes P > 13 up to P=50
primes_P = [17, 19, 23, 29, 31, 37, 41, 43, 47]
solutions = []

for P in primes_P:
    solution = check_solution(P)
    if solution:
        solutions.append(solution)

print(solutions)
